python3 -c "
import random
from attack import f_function
random.seed(1)
xs=[random.getrandbits(32) for _ in range(2000)]
def test(d):
    vals=set(f_function(x^d)^f_function(x) for x in xs)
    return vals
# all single-byte differences
found=[]
for i in range(4):
    for b in range(1,256):
        d=b<<(8*i)
        v=test(d)
        if len(v)==1:
            found.append((d,next(iter(v))))
print('single-byte deterministic:', [(hex(a),hex(b)) for a,b in found])
# top-bit per byte masks
for mask in range(16):
    d=0
    for i in range(4):
        if mask>>i & 1: d|=0x80<<(8*i)
    v=test(d)
    if len(v)==1:
        print('mask',hex(d),'->',hex(next(iter(v))))
"
